<script setup lang="ts">
import{onMounted,ref}from'vue';import{vendorAPI,authPasswordAPI,getApiErrorMessage}from'../../services/api';import type{Vendor}from'../../services/api';
const vendor=ref<Vendor|null>(null),loading=ref(true),saving=ref(false),error=ref(''),message=ref(''),current=ref(''),next=ref('');async function load(){loading.value=true;try{vendor.value=await vendorAPI.getProfile()}catch(e:unknown){error.value=getApiErrorMessage(e,'Profile could not be loaded.')}finally{loading.value=false}}async function change(){if(next.value.length<8){error.value='New password must be at least 8 characters.';return}saving.value=true;error.value='';message.value='';try{await authPasswordAPI.changePassword(current.value,next.value);message.value='Password changed successfully.';current.value='';next.value=''}catch(e:unknown){error.value=getApiErrorMessage(e,'Password could not be changed.')}finally{saving.value=false}}onMounted(load)
</script><template><main class="vendor-main"><header class="page-head"><p>ACCOUNT</p><h1>Vendor Profile</h1></header><div v-if="loading" class="state">Loading profile...</div><div v-else-if="!vendor" class="state error">{{error}}</div><template v-else><section class="profile-card"><div class="code">{{vendor.code}}</div><dl><div><dt>Business name</dt><dd>{{vendor.business_name}}</dd></div><div><dt>Contact name</dt><dd>{{vendor.contact_name||'-'}}</dd></div><div><dt>Email</dt><dd>{{vendor.email}}</dd></div><div><dt>Phone</dt><dd>{{vendor.phone||'-'}}</dd></div><div><dt>Status</dt><dd>{{vendor.status}}</dd></div></dl></section><section class="password-card"><h2>Change password</h2><div v-if="message" class="success">{{message}}</div><div v-if="error" class="error">{{error}}</div><form @submit.prevent="change"><label>Current password<input v-model="current" type="password" required :disabled="saving"/></label><label>New password<input v-model="next" type="password" minlength="8" maxlength="72" required :disabled="saving"/></label><button :disabled="saving">{{saving?'Changing...':'Change password'}}</button></form></section></template></main></template><style scoped>.vendor-main{padding:18px 28px}.page-head p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.page-head h1{margin:4px 0 16px}.profile-card,.password-card{padding:20px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.profile-card{margin-bottom:14px}.code{display:inline-flex;padding:9px 13px;border-radius:999px;background:#075397;color:#fff;font-weight:850}.profile-card dl{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:18px 0 0}.profile-card dl div{padding:10px;background:#f7f9fb;border-radius:6px}.profile-card dt{color:#64748b;font-size:.72rem}.profile-card dd{margin:4px 0 0;font-weight:750}.password-card h2{margin:0 0 12px;font-size:1rem}.password-card form{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end}.password-card label{display:flex;flex-direction:column;gap:6px;font-size:.78rem;font-weight:750}.password-card input{height:42px;padding:0 10px;border:1px solid #cbd5e1;border-radius:6px}.password-card button{height:42px;padding:0 14px;border:0;border-radius:6px;background:#ff7900;color:#fff;font-weight:800}.success,.error,.state{padding:10px;border-radius:6px;margin-bottom:10px}.success{background:#e8f7ef;color:#18794e}.error{background:#feeaea;color:#b42318}@media(max-width:700px){.vendor-main{padding:14px}.profile-card dl,.password-card form{grid-template-columns:1fr}}</style>